/** Endpoints kept per node (the root endpoint not counted). */
#define MESP_MAX_EPS 8

/** Last known on/off, brightness and color temperature of an endpoint (-1 = unknown). */
struct mesp_endpoint_state_t {
    int8_t on;
    int16_t level;  // LevelControl CurrentLevel, 0..254
    int32_t ct;     // ColorControl ColorTemperatureMireds
    int32_t ct_min; // ColorTempPhysicalMinMireds (coolest)
    int32_t ct_max; // ColorTempPhysicalMaxMireds (warmest)
};

/** Last reported sensor values of an endpoint. */
struct mesp_measure_t {
    int16_t temp;        // TemperatureMeasurement MeasuredValue, 0.01 °C
    uint16_t humidity;   // RelativeHumidityMeasurement MeasuredValue, 0.01 %
    int64_t temp_at;     // esp_timer µs, 0 = never reported
    int64_t humidity_at; // esp_timer µs, 0 = never reported
};

/** Last reported battery of a node (Power Source cluster). */
struct mesp_battery_t {
    int16_t percent_x2; // BatPercentRemaining in half percent (0..200), -1 = unknown
    int8_t level;       // BatChargeLevel: 0 ok, 1 warning, 2 critical, -1 = unknown
    int64_t updated;    // esp_timer µs, 0 = never reported
};

/**
 * Last read power draw (Electrical Power Measurement) and energy total (Electrical Energy
 * Measurement) of a node. Often on an endpoint of their own.
 */
struct mesp_power_t {
    int64_t mw;             // ActivePower in mW
    uint16_t ep;            // endpoint that reported it
    int64_t updated;        // esp_timer µs, 0 = never read
    int64_t energy_mwh;     // CumulativeEnergyImported in mWh
    int64_t energy_updated; // esp_timer µs, 0 = never read
};

/** Size of a node's name, including the terminating 0. */
#define MESP_NODE_NAME_LEN 32

/** A node's last known values (mesp_matter_on_values). The pointers are valid during the call only. */
struct mesp_node_values {
    uint64_t node_id;
    const char *name; // "" if none
    const mesp_battery_t *battery;
    const mesp_power_t *power;
    uint8_t ep_count;
    const uint16_t *ep;                 // ep_count endpoints
    const mesp_measure_t *measure;      // per endpoint
    const mesp_endpoint_state_t *state; // per endpoint: on/off, brightness, color temperature
};

/**
 * `current`: the node reported (values changed), or its values are no longer current – it went
 * offline, is being removed or renamed (a call with the new name follows). Called with the nodes
 * lock held: don't block.
 */
typedef void (*mesp_values_cb_t)(const mesp_node_values &node, bool current);
/** Get the values of all nodes as they change, e.g. to send them as metrics. Call at startup. */
void mesp_matter_on_values(mesp_values_cb_t cb);
